# longest first
R=sorted(R.items(), key=lambda kv: len(kv[0]), reverse=True)
for t in s.find_all(string=True):
    if t.parent.name in ['script','style'] or not t.strip(): continue
    x=str(t)
    if not re.search(r'[\u0600-\u06ff]',x): continue
    # don't alter strings that are clearly already Kurdish unless they contain Persian fragments
    y=x
    for a,b in R: y=y.replace(a,b)
    if y!=x: t.replace_with(y)
open(p,'w',encoding='utf8').write(str(s))
